// District name normalization map (matching standard prototype district names)
export const DISTRICT_NAME_ALIASES = {
  'Kamrup': 'Kamrup Metro',
  'Kamrup Metro': 'Kamrup',
  'North Cachar Hills': 'Dima Hasao',
  'Dima Hasao': 'North Cachar Hills',
  'Sibsagar': 'Sivasagar',
  'Marigaon': 'Morigaon',
  'West Imphal': 'Imphal West',
  'Imphal West': 'West Imphal',
  'East Imphal': 'Imphal East',
  'Imphal East': 'East Imphal',
  'Jaintia Hills': 'East Jaintia Hills',
  'East Jaintia Hills': 'Jaintia Hills',
  'East': 'East Sikkim',
  'East Sikkim': 'East',
  'West': 'West Sikkim',
  'West Sikkim': 'West'
};

export function normalizeDistrictName(name) {
  if (!name) return '';
  return DISTRICT_NAME_ALIASES[name] || name;
}

// Compute Bounding Box for a GeoJSON feature: [minLon, minLat, maxLon, maxLat]
function getFeatureBBox(feature) {
  let minLon = Infinity, minLat = Infinity, maxLon = -Infinity, maxLat = -Infinity;
  function walk(coords) {
    if (typeof coords[0] === 'number') {
      const [lon, lat] = coords;
      if (lon < minLon) minLon = lon;
      if (lat < minLat) minLat = lat;
      if (lon > maxLon) maxLon = lon;
      if (lat > maxLat) maxLat = lat;
    } else {
      for (let i = 0; i < coords.length; i++) walk(coords[i]);
    }
  }
  walk(feature.geometry.coordinates);
  return [minLon, minLat, maxLon, maxLat];
}

// Attach BBoxes to district features for ultra-fast point-in-polygon queries
const DISTRICT_FEATURES_WITH_BBOX = NER_DISTRICTS_GEOJSON.features.map(f => ({
  feature: f,
  bbox: getFeatureBBox(f)
}));

function isPointInPolygonRing(lat, lon, ring) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const xi = ring[i][0], yi = ring[i][1];
    const xj = ring[j][0], yj = ring[j][1];
    const intersect = ((yi > lat) !== (yj > lat)) &&
        (lon < (xj - xi) * (lat - yi) / (yj - yi) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function isPointInGeometry(lat, lon, geom) {
  if (!geom) return false;
  if (geom.type === 'Polygon') {
    return isPointInPolygonRing(lat, lon, geom.coordinates[0]);
  } else if (geom.type === 'MultiPolygon') {
    for (let p = 0; p < geom.coordinates.length; p++) {
      if (isPointInPolygonRing(lat, lon, geom.coordinates[p][0])) return true;
    }
  }
  return false;
}

/**
 * Fast point-in-polygon to find which district and state a GPS coordinate is in.
 * @param {number} lat - Latitude
 * @param {number} lon - Longitude
 * @returns {{ districtName: string, stateName: string } | null}
 */
export function getDistrictForPoint(lat, lon) {
  for (let i = 0; i < DISTRICT_FEATURES_WITH_BBOX.length; i++) {
    const item = DISTRICT_FEATURES_WITH_BBOX[i];
    const [minLon, minLat, maxLon, maxLat] = item.bbox;
    if (lon >= minLon && lon <= maxLon && lat >= minLat && lat <= maxLat) {
      if (isPointInGeometry(lat, lon, item.feature.geometry)) {
        return {
          districtName: item.feature.properties.districtName,
          stateName: item.feature.properties.stateName
        };
      }
    }
  }
  return null;
}

/**
 * Identify all unique districts traversed by a route polyline in order.
 * @param {Array<[number, number]>} coordinates - Array of [lat, lon] waypoints
 * @returns {Array<{ districtName: string, stateName: string }>}
 */
export function getDistrictsForRoute(coordinates) {
  if (!coordinates || coordinates.length === 0) return [];
  const traversed = [];
  const seen = new Set();

  // Sample every ~5th point or endpoints to keep it fast while catching all crossed districts
  const step = Math.max(1, Math.floor(coordinates.length / 45));
  for (let i = 0; i < coordinates.length; i += step) {
    const [lat, lon] = coordinates[i];
    const match = getDistrictForPoint(lat, lon);
    if (match) {
      const key = `${match.districtName}_${match.stateName}`;
      if (!seen.has(key)) {
        seen.add(key);
        traversed.push(match);
      }
    }
  }
  // Ensure last point is included
  const lastPt = coordinates[coordinates.length - 1];
  const lastMatch = getDistrictForPoint(lastPt[0], lastPt[1]);
  if (lastMatch) {
    const key = `${lastMatch.districtName}_${lastMatch.stateName}`;
    if (!seen.has(key)) {
      traversed.push(lastMatch);
    }
  }
  return traversed;
}
